CREATE TABLE payment_provider_orders(payment_id TEXT PRIMARY KEY REFERENCES payments(id), bill_id TEXT NOT NULL REFERENCES bills(id), out_trade_no TEXT NOT NULL UNIQUE, merchant_id TEXT NOT NULL, app_id TEXT NOT NULL, actor TEXT NOT NULL REFERENCES users(actor), binding_version INTEGER NOT NULL, payer_hash TEXT NOT NULL, status TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), prepay_id TEXT, provider_transaction TEXT UNIQUE, last_error TEXT, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX real_payment_active_bill ON payment_provider_orders(bill_id) WHERE status IN ('creating','pending','success');
CREATE TABLE payment_idempotency(subject TEXT NOT NULL, request_key TEXT NOT NULL, bill_id TEXT NOT NULL, payment_id TEXT NOT NULL REFERENCES payment_provider_orders(payment_id), PRIMARY KEY(subject,request_key));
CREATE TABLE payment_notifications(id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id), body_digest TEXT NOT NULL, received_at TEXT NOT NULL);
